#!/usr/bin/env node
/**
 * Generate the main-process @drone/plugin-api shim from the renderer manifest.
 *
 * The generated file is committed so packaged builds do not depend on a
 * runtime TypeScript loader. `--check` is used by CI to make drift visible.
 */
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import process from "node:process";

const root = new URL("../", import.meta.url);
const manifestPath = new URL("./src/renderer/src/plugins/host-api.manifest.ts", root);
const outputPath = new URL("./src/main/ui-plugins/plugin-api-shim.generated.ts", root);

const manifestSource = await readFile(manifestPath, "utf8");

function readNames(namespace) {
	const match = new RegExp(`${namespace}:\\s*\\[([\\s\\S]*?)\\]`).exec(manifestSource);
	if (!match) throw new Error(`Plugin host API manifest is missing ${namespace}`);
	return [...match[1].matchAll(/"([^"]+)"/g)].map((item) => item[1]);
}

const names = {
	components: readNames("components"),
	helpers: readNames("helpers"),
	hooks: readNames("hooks"),
	stores: readNames("stores"),
	i18n: readNames("i18n"),
};

const shim = [
	"const A = window.DroneUI;",
	"export default A;",
	"export const { version, components, helpers, hooks, stores, i18n } = A;",
	`export const { ${names.components.join(", ")} } = A.components;`,
	`export const { ${names.helpers.join(", ")} } = A.helpers;`,
	`export const { ${names.hooks.join(", ")} } = A.hooks;`,
	`export const { ${names.stores.join(", ")} } = A.stores;`,
	`export const { ${names.i18n.join(", ")} } = A.i18n;`,
].join("\n");

const output = `/** Generated by packages/desktop/scripts/gen-plugin-api.mjs. Do not edit by hand. */\nexport const PLUGIN_API_SHIM =\n\t${JSON.stringify(`${shim}\n`)};\n`;
const check = process.argv.includes("--check");
if (check) {
	const current = await readFile(outputPath, "utf8").catch(() => "");
	if (current !== output) {
		console.error(
			`Generated plugin API shim is stale: ${join("packages/desktop", "src/main/ui-plugins/plugin-api-shim.generated.ts")}`,
		);
		process.exit(1);
	}
	console.log("plugin host API shim is up to date");
} else {
	await writeFile(outputPath, output, "utf8");
	console.log("generated plugin host API shim");
}
